  }

  for (const step of steps) {
    if (step.repro_cmd) {
      const err = checkText(step.repro_cmd, step.n)
      if (err) return err
    }
  }
  if (bundlePath) {
    const err = checkText(bundlePath)
    if (err) return err
  }
  return null
}

